using System;using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckMattressRacing.Editor {public static class MattressFixtures {public static void Run(){int n=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Mattress fixture: "+label);n++;};var s=new SportsRaceSeries();s.Reset(8,true);s.BeginRound();s.Resolve(new[]{1f,2f,3f,4f,5f,6f,7f,float.PositiveInfinity});check(s.total[0]==8&&s.total[6]==2&&s.total[7]==0,"placement points and DNF zero");check(!s.Resolve(new[]{1f,2f,3f,4f,5f,6f,7f,8f})&&s.completed==1,"round finalizes once");s.Reset(4,false);for(int r=0;r<3;r++){s.BeginRound();s.Resolve(new[]{1f,1f,3f,float.PositiveInfinity});}check(s.winner<0&&s.eligible==3,"true tied leaders enter extra race");s.BeginRound();s.Resolve(new[]{2f,1f,float.PositiveInfinity,float.PositiveInfinity});check(s.winner==1,"extra actual finish resolves tie");s.Reset(4,true);s.BeginRound();s.Resolve(new[]{1f,2f,3f,4f});s.BeginRound();s.Resolve(new[]{2f,1f,3f,4f});s.BeginRound();s.Resolve(new[]{2f,1f,3f,4f});check(s.winner==1,"best total after three races");check(s.finishes[8]==2&&s.finishes[0]==1,"best-place histogram recorded");s.Reset(8,true);s.BeginRound();s.Resolve(new[]{1f,2f,3f,4f,5f,6f,7f,8f});s.BeginRound();s.Resolve(new[]{float.PositiveInfinity,3f,1f,2f,4f,5f,6f,7f});s.BeginRound();s.Resolve(new[]{1f,6f,float.PositiveInfinity,float.PositiveInfinity,2f,3f,4f,5f});check(s.total[0]==16&&s.total[1]==16&&s.total[4]==16&&s.winner==0,"best finishing positions resolve equal total leaders");Debug.Log("MATTRESS_RULE_FIXTURES_PASS count="+n);}}}
